    30      inline
    31      bool is_control_character(uint32_t c)
    32      {
    33          return c <= 0x1F || c == 0x7f;
    34      }
    35
    36      inline
    37      bool is_non_ascii_codepoint(uint32_t cp)
    38      {
    39          return cp >= 0x80;
    40      }
