   599          bool visit_key(const string_view_type& name, const ser_context&, std::error_code&) override
   600          {
   601              JSONCONS_ASSERT(!stack_.empty());
   602              if (stack_.back().count() > 0)
   603              {
   604                  sink_.append(comma_str_.data(),comma_str_.length());
   605                  column_ += comma_str_.length();
   606              }
   607
   608              if (stack_.back().is_multi_line())
   609              {
   610                  stack_.back().new_line_after(true);
   611                  new_line();
   612              }
   613              else if (stack_.back().count() > 0 && column_ >= options_.line_length_limit())
   614              {
   615                  //stack_.back().new_line_after(true);
   616                  new_line(stack_.back().data_pos());
   617              }
   618
   619              if (stack_.back().count() == 0)
   620              {
   621                  stack_.back().set_position(column_);
   622              }
   623              sink_.push_back('\"');
   624              std::size_t length = jsoncons::detail::escape_string(name.data(), name.length(),options_.escape_all_non_ascii(),options_.escape_solidus(),sink_);
   625              sink_.push_back('\"');
   626              sink_.append(colon_str_.data(),colon_str_.length());
   627              column_ += (length+2+colon_str_.length());
   628              return true;
