   637                      begin_scalar_value();
   638                  }
   639                  if (!stack_.back().is_multi_line() && column_ >= options_.line_length_limit())
   640                  {
   641                      break_line();
   642                  }
   643              }
   644
   645              sink_.append(null_k().data(), null_k().size());
   646              column_ += null_k().size();
