    58      template <class Byte>
    59      typename std::enable_if<jsoncons::detail::is_byte<Byte>::value,detect_encoding_result<Byte>>::type
    60      detect_encoding_from_bom(const Byte* data, std::size_t length)
    61      {
    62          const uint8_t bom_utf8[] = {0xef,0xbb,0xbf};
    63          const uint8_t bom_utf16le[] = {0xff,0xfe};
    64          const uint8_t bom_utf16be[] = {0xfe,0xff};
    65          const uint8_t bom_utf32le[] = {0xff,0xfe,0x00,0x00};
    66          const uint8_t bom_utf32be[] = {0x00,0x00,0xfe,0xff};
    67
    68          if (length >= 4 && !memcmp(data,bom_utf32le,4))
    69          {
    70              return detect_encoding_result<Byte>{data+4,encoding_kind::utf32le};
    71          }
    72          else if (length >= 4 && !memcmp(data,bom_utf32be,4))
    73          {
    74              return detect_encoding_result<Byte>{data+4,encoding_kind::utf32be};
    75          }
    76          else if (length >= 2 && !memcmp(data,bom_utf16le,2))
    77          {
    78              return detect_encoding_result<Byte>{data+2,encoding_kind::utf16le};
    79          }
    80          else if (length >= 2 && !memcmp(data,bom_utf16be,2))
    81          {
    82              return detect_encoding_result<Byte>{data+2,encoding_kind::utf16be};
    83          }
    84          else if (length >= 3 && !memcmp(data,bom_utf8,3))
    85          {
    86              return detect_encoding_result<Byte>{data+3,encoding_kind::utf8};
    87          }
    88          else
    89          {
    90              return detect_encoding_result<Byte>{data,encoding_kind::undetected};
    91          }
    92      }
