   421      // to_codepoint
   422
   423      template <class CharT,class CodepointT>
   424      typename std::enable_if<std::is_integral<CharT>::value && sizeof(CharT) == sizeof(uint8_t)
   425                              && std::is_integral<CodepointT>::value && sizeof(CodepointT) == sizeof(uint32_t),
   426                              convert_result<CharT>>::type
   427      to_codepoint(const CharT* first, const CharT* last,
   428                   CodepointT& ch,
   429                   conv_flags flags = conv_flags::strict)
   430      {
   431          if (first >= last)
   432          {
   433              return convert_result<CharT>{first, conv_errc::source_exhausted};
   434          }
   435          conv_errc  result = conv_errc();
   436
   437          unsigned short extra_bytes_to_read = trailing_bytes_for_utf8[static_cast<uint8_t>(*first)];
   438          if (extra_bytes_to_read >= last - first)
   439          {
   440              result = conv_errc::source_exhausted;
   441              return convert_result<CharT>{first, result};
   442          }
   443          // Do this check whether lenient or strict
   444          if ((result=is_legal_utf8(first, extra_bytes_to_read+1)) != conv_errc())
   445          {
   446              return convert_result<CharT>{first, result};
   447          }
   448          // The cases all fall through. See "Note A" below.
   449          ch = 0;
   450          switch (extra_bytes_to_read)
   451          {
   452              case 5:
   453                  ch += static_cast<uint8_t>(*first++);
   454                  ch <<= 6;
   455                  JSONCONS_FALLTHROUGH;
   456              case 4:
   457                  ch += static_cast<uint8_t>(*first++);
   458                  ch <<= 6;
   459                  JSONCONS_FALLTHROUGH;
   460              case 3:
   461                  ch += static_cast<uint8_t>(*first++);
   462                  ch <<= 6;
   463                  JSONCONS_FALLTHROUGH;
   464              case 2:
   465                  ch += static_cast<uint8_t>(*first++);
   466                  ch <<= 6;
   467                  JSONCONS_FALLTHROUGH;
   468              case 1:
   469                  ch += static_cast<uint8_t>(*first++);
   470                  ch <<= 6;
   471                  JSONCONS_FALLTHROUGH;
   472              case 0:
   473                  ch += static_cast<uint8_t>(*first++);
   474                  break;
   475          }
   476          ch -= offsets_from_utf8[extra_bytes_to_read];
   477
   478          if (ch <= max_legal_utf32) {
   479              /*
   480               * UTF-16 surrogate values are illegal in UTF-32, and anything
   481               * over Plane 17 (> 0x10FFFF) is illegal.
   482               */
   483              if (is_surrogate(ch) )
   484              {
   485                  if (flags == conv_flags::strict)
   486                  {
   487                      first -= (extra_bytes_to_read+1); // return to the illegal value itself
   488                      result = conv_errc::source_illegal;
   489                      return convert_result<CharT>{first, result};
   490                  }
   491                  else
   492                  {
   493                      ch = replacement_char;
   494                  }
   495              }
   496          }
   497          else // i.e., ch > max_legal_utf32
   498          {
   499              result = conv_errc::source_illegal;
   500              ch = replacement_char;
   501          }
   502
   503          return convert_result<CharT>{first,result} ;
   504      }
