   506      template <class CharT,class CodepointT>
   507      typename std::enable_if<std::is_integral<CharT>::value && sizeof(CharT) == sizeof(uint16_t)
   508                              && std::is_integral<CodepointT>::value && sizeof(CodepointT) == sizeof(uint32_t),
   509                              convert_result<CharT>>::type
   510      to_codepoint(const CharT* first, const CharT* last,
   511                   CodepointT& ch,
   512                   conv_flags flags = conv_flags::strict)
   513      {
   514          if (first >= last)
   515          {
   516              return convert_result<CharT>{first, conv_errc::source_exhausted};
   517          }
   518          conv_errc  result = conv_errc();
   519
   520          ch = *first++;
   521          // If we have a surrogate pair, convert to UTF32 first.
   522          if (is_high_surrogate(ch)) {
   523              // If the 16 bits following the high surrogate are in the first buffer...
   524              if (first < last)
   525              {
   526                  uint32_t ch2 = *first;
   527                  // If ptr's a low surrogate, convert to UTF32.
   528                  if (ch2 >= sur_low_start && ch2 <= sur_low_end ) {
   529                      ch = ((ch - sur_high_start) << half_shift)
   530                          + (ch2 - sur_low_start) + half_base;
   531                      ++first;
   532                  }
   533                  else if (flags == conv_flags::strict) // ptr's an unpaired high surrogate
   534                  {
   535                      --first; /* return to the illegal value itself */
   536                      result = conv_errc::source_illegal;
   537                      return convert_result<CharT>{first, result};
   538                  }
   539              }
   540              else
   541              { /* We don't have the 16 bits following the high surrogate. */
   542                  --first; /* return to the high surrogate */
   543                  result = conv_errc::source_exhausted;
   544                  return convert_result<CharT>{first, result};
   545              }
   546          } else if (flags == conv_flags::strict) {
   547              /* UTF-16 surrogate values are illegal in UTF-32 */
   548              if (is_low_surrogate(ch) )
   549              {
   550                  --first; /* return to the illegal value itself */
   551                  result = conv_errc::source_illegal;
   552                  return convert_result<CharT>{first, result};
   553              }
   554          }
   555
   556          return convert_result<CharT>{first,result} ;
   557      }
