   560      typename std::enable_if<std::is_integral<CharT>::value && sizeof(CharT) == sizeof(uint32_t)
   561                              && std::is_integral<CodepointT>::value && sizeof(CodepointT) == sizeof(uint32_t),
   562                              convert_result<CharT>>::type
   563      to_codepoint(const CharT* first, const CharT* last,
   564                   CodepointT& ch,
   565                   conv_flags flags = conv_flags::strict)
   566      {
   567          if (first >= last)
   568          {
   569              return convert_result<CharT>{first, conv_errc::source_exhausted};
   570          }
   571          conv_errc  result = conv_errc();
   572
   573          ch = *first++;
   574          if (flags == conv_flags::strict ) {
   575              /* UTF-16 surrogate values are illegal in UTF-32 */
   576              if (is_surrogate(ch))
   577              {
   578                  --first; /* return to the illegal value itself */
   579                  result = conv_errc::illegal_surrogate_value;
   580                  return convert_result<CharT>{first,result} ;
   581              }
   582          }
   583          if (!(ch <= max_legal_utf32))
   584          {
   585              ch = replacement_char;
   586              result = conv_errc::source_illegal;
   587          }
   588
   589          return convert_result<CharT>{first,result} ;
   590      }
